#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char   ad[30];
    int    numara;
    double ortalama;
} Ogrenci;

int main(void) {
    int n;
    scanf("%d", &n);

    Ogrenci *o = (Ogrenci *)malloc(n * sizeof(Ogrenci));
    if (o == NULL) { printf("Bellek yetersiz\n"); return 1; }

    for (int i = 0; i < n; i++)
        scanf("%29s %d %lf", o[i].ad, &o[i].numara, &o[i].ortalama);

    FILE *f = fopen("ogrenci.txt", "w");
    if (f == NULL) { free(o); return 1; }
    for (int i = 0; i < n; i++)
        fprintf(f, "%s %d %.2f\n", o[i].ad, o[i].numara, o[i].ortalama);
    fclose(f);

    f = fopen("ogrenci.txt", "r");
    if (f == NULL) { free(o); return 1; }

    Ogrenci t;
    printf("Ortalamasi 60 ustu:\n");
    while (fscanf(f, "%29s %d %lf", t.ad, &t.numara, &t.ortalama) == 3)
        if (t.ortalama > 60)
            printf("%-10s %d %.2f\n", t.ad, t.numara, t.ortalama);
    fclose(f);

    free(o);
    return 0;
}
```

Dikkat edilecekler: `o[i].ad` bir dizi olduğu için `scanf`te `&` almaz, ama `&o[i].numara` alır. `fscanf`in dönüş değerini 3 ile karşılaştırmak, dosya sonunu ve bozuk satırları birlikte yakalar. Her `malloc` için bir `free`, her `fopen` için bir `fclose` yazıldığına dikkat edin.
